function hasMultipleStretch(nums: number[], k: number): boolean {
  const pre = [0];
  for (const x of nums) pre.push(pre[pre.length - 1] + x);
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 2; j <= nums.length; j++) {
      if ((pre[j] - pre[i]) % k === 0) return true;
    }
  }
  return false;
}

