function hasMultipleStretch(nums: number[], k: number): boolean {
  const first = new Map<number, number>([[0, 0]]);
  let s = 0;
  for (let i = 0; i < nums.length; i++) {
    s = (s + nums[i]) % k; // keep only the remainder so the sum stays small
    const seen = first.get(s);
    if (seen === undefined) first.set(s, i + 1);
    else if (i + 1 - seen >= 2) return true;
  }
  return false;
}

